from itertools import permutations

PEOPLE = ['Blake', 'Harper', 'Morgan', 'Parker', 'Riley']
COLORS = ['blue', 'orange', 'red', 'white', 'yellow']
PETS = ['bird', 'cat', 'fish', 'horse', 'rabbit']
DRINKS = ['coffee', 'juice', 'milk', 'tea', 'water']
HOBBIES = ['chess', 'fencing', 'hiking', 'painting', 'rowing']

def is_valid(people, colors, pets, drinks, hobbies):
    pos = {people[i]: i for i in range(5)}

    # Clue 1: hiking -> yellow house
    for i in range(5):
        if hobbies[i] == 'hiking' and colors[i] != 'yellow':
            return False

    # Clue 2: cat owner next to white house
    for i in range(5):
        if pets[i] == 'cat':
            if not ((i > 0 and colors[i-1] == 'white') or (i < 4 and colors[i+1] == 'white')):
                return False

    # Clue 3: juice immediately left of Riley
    if pos['Riley'] == 0 or drinks[pos['Riley'] - 1] != 'juice':
        return False

    # Clue 4: Riley is not bird owner
    if pets[pos['Riley']] == 'bird':
        return False

    # Clue 5: water -> blue house
    for i in range(5):
        if drinks[i] == 'water' and colors[i] != 'blue':
            return False

    # Clue 6: Blake next to rowing person
    blake_pos = pos['Blake']
    if not ((blake_pos > 0 and hobbies[blake_pos-1] == 'rowing') or (blake_pos < 4 and hobbies[blake_pos+1] == 'rowing')):
        return False

    # Clue 7: Harper immediately left of horse owner
    harper_pos = pos['Harper']
    if harper_pos == 4 or pets[harper_pos + 1] != 'horse':
        return False

    # Clue 8: coffee immediately left of rabbit owner
    for i in range(1, 5):
        if pets[i] == 'rabbit' and drinks[i-1] != 'coffee':
            return False

    # Clue 9: Parker next to tea drinker
    parker_pos = pos['Parker']
    if not ((parker_pos > 0 and drinks[parker_pos-1] == 'tea') or (parker_pos < 4 and drinks[parker_pos+1] == 'tea')):
        return False

    # Clue 10: fencing -> milk
    for i in range(5):
        if hobbies[i] == 'fencing' and drinks[i] != 'milk':
            return False

    # Clue 11: chess immediately left of juice
    for i in range(1, 5):
        if drinks[i] == 'juice' and hobbies[i-1] != 'chess':
            return False

    # Clue 12: rabbit immediately left of yellow house
    for i in range(1, 5):
        if colors[i] == 'yellow' and pets[i-1] != 'rabbit':
            return False

    # Clue 13: Parker does fencing
    if hobbies[pos['Parker']] != 'fencing':
        return False

    # Clue 14: fish -> red house
    for i in range(5):
        if pets[i] == 'fish' and colors[i] != 'red':
            return False

    # Clue 15: Blake immediately left of bird owner
    blake_pos = pos['Blake']
    if blake_pos == 4 or pets[blake_pos + 1] != 'bird':
        return False

    return True

found = False
for people in permutations(PEOPLE):
    if found:
        break
    for colors in permutations(COLORS):
        if found:
            break
        for pets in permutations(PETS):
            if found:
                break
            for drinks in permutations(DRINKS):
                if found:
                    break
                for hobbies in permutations(HOBBIES):
                    if is_valid(people, colors, pets, drinks, hobbies):
                        for i in range(5):
                            if colors[i] == 'red':
                                print(f"ANSWER: {people[i]}")
                        found = True
                        break
